#!/bin/bashecho "🚀 TK1971 Avaitor AI System Installation"echo "========================================"# ColorsRED='\033[0;31m'GREEN='\033[0;32m'YELLOW='\033[1;33m'NC='\033[0m'# Check if running as rootif [ "$EUID" -ne 0 ]; then     echo -e "${YELLOW}⚠️  Running as non-root user${NC}"fiecho -e "\n📦 Step 1: System Update"sudo apt-get update -ysudo apt-get upgrade -yecho -e "\n🐍 Step 2: Install Python"sudo apt-get install -y python3 python3-pip python3-venvecho -e "\n🔧 Step 3: Create Virtual Environment"python3 -m venv venvsource venv/bin/activateecho -e "\n📦 Step 4: Install Python Packages"pip install --upgrade pippip install -r requirements.txtecho -e "\n🌐 Step 5: Install Chrome (Optional for scraping)"read -p "Install Chrome for web scraping? (y/n): " install_chromeif [ "$install_chrome" = "y" ]; then    wget -q -O - https://dl.google.com/linux/linux_signing_key.pub | sudo apt-key add -    echo "deb [arch=amd64] http://dl.google.com/linux/chrome/deb/ stable main" | sudo tee /etc/apt/sources.list.d/google-chrome.list    sudo apt-get update    sudo apt-get install -y google-chrome-stable        # Install ChromeDriver    CHROME_VERSION=$(google-chrome --version | cut -d ' ' -f3 | cut -d '.' -f1)    CHROME_DRIVER_VERSION=$(curl -s "https://chromedriver.storage.googleapis.com/LATEST_RELEASE_$CHROME_VERSION")    wget -q "https://chromedriver.storage.googleapis.com/$CHROME_DRIVER_VERSION/chromedriver_linux64.zip"    unzip chromedriver_linux64.zip    sudo mv chromedriver /usr/local/bin/    sudo chmod +x /usr/local/bin/chromedriver    rm chromedriver_linux64.zipfiecho -e "\n📁 Step 6: Create Directories"mkdir -p logs models data screenshotsecho -e "\n🔧 Step 7: Create .env file"cat > .env << EOF# TK1971 CredentialsTK1971_PHONE=09638427727TK1971_PASSWORD=s2TnYT7jhShTK1971_URL=https://www.tk1971.io# TelegramTELEGRAM_TOKEN=8539278490:AAFyg0ZxejKkiU1xUzCOPzmuB7B6amcbrIMTELEGRAM_CHANNEL=@Avaitor_live_signal_channel# SystemLEARNING_MINUTES=5CHECK_INTERVAL=1.0USE_AI=trueDEBUG_MODE=falseSAVE_SCREENSHOTS=falseEOFecho -e "\n🛠️  Step 8: Make scripts executable"chmod +x start_system.pychmod +x tk1971_live_system.pyecho -e "\n✅ ${GREEN}Installation Complete!${NC}"echo -e "\n📋 Next Steps:"echo -e "1. Edit .env file if needed"echo -e "2. Start system: ${YELLOW}python start_system.py${NC}"echo -e "3. Check logs: ${YELLOW}tail -f logs/tk1971_live.log${NC}"echo -e "\n🎯 ${GREEN}System will run 24/7 with auto-restart!${NC}"